from rules import resolve


def solve(data):
    return resolve(data)

def resolve(data):
    packages = data["packages"]
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = data.get("features", [])
    names = sorted(packages)
    best_score = None
    best_versions = None

    def is_acyclic(graph):
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for dependency in graph.get(name, []):
                if not visit(dependency):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in graph)

    def search(assigned, bounds, graph):
        nonlocal best_score, best_versions

        pending = [name for name in bounds if name not in assigned]
        if not pending:
            if not is_acyclic(graph):
                return
            score = tuple(assigned.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = dict(assigned)
            return

        name = min(pending)
        if name not in packages:
            return

        low, high = bounds[name]
        forbidden = blocked.get(name, [])
        for row in packages[name]:
            version = row["version"]
            if not low <= version <= high or version in forbidden:
                continue
            if name in pins and version != pins[name]:
                continue

            deps = row["deps"]
            if not isinstance(deps, list):
                continue

            next_bounds = dict(bounds)
            edges = []
            valid = True
            for dep in deps:
                if not isinstance(dep, dict) or not all(
                    key in dep for key in ("name", "min", "max")
                ):
                    valid = False
                    break

                feature = dep.get("feature")
                if feature and feature not in features:
                    continue

                dep_name = dep["name"]
                if not isinstance(dep_name, str) or dep_name not in packages:
                    valid = False
                    break

                dep_low, dep_high = dep["min"], dep["max"]
                if dep_name in next_bounds:
                    old_low, old_high = next_bounds[dep_name]
                    dep_low = max(dep_low, old_low)
                    dep_high = min(dep_high, old_high)
                if dep_low > dep_high:
                    valid = False
                    break
                if dep_name in assigned and not (
                    dep_low <= assigned[dep_name] <= dep_high
                ):
                    valid = False
                    break
                next_bounds[dep_name] = (dep_low, dep_high)
                edges.append(dep_name)

            if valid and name in next_bounds:
                chosen_low, chosen_high = next_bounds[name]
                if not chosen_low <= version <= chosen_high:
                    valid = False

            if valid:
                next_assigned = dict(assigned)
                next_assigned[name] = version
                next_graph = dict(graph)
                next_graph[name] = edges
                search(next_assigned, next_bounds, next_graph)

    bounds = {}
    for name, interval in roots.items():
        if name not in packages:
            return {"error": "unsatisfiable"}
        bounds[name] = (interval[0], interval[1])

    search({}, bounds, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}
